const rows = $input.all().map(i => i.json);

// Group by schema → table → columns
const schemas = {};
for (const row of rows) {
  const key = `${row.schema_name}.${row.table_name}`;
  if (!schemas[key]) schemas[key] = [];

  let col = `  - ${row.column_name} (${row.data_type}`;
  if (row.is_pk === 'PK') col += ', PRIMARY KEY';
  if (row.is_fk === 'FK') col += ', FK';
  if (row.is_nullable === false || row.is_nullable === 0) col += ', NOT NULL';
  if (row.check_constraint) col += `, CHECK: ${row.check_constraint}`;
  col += ')';

  schemas[key].push(col);
}

// Build readable markdown
let schemaText = '# UHIP Database Schema\n\n';
for (const [table, cols] of Object.entries(schemas)) {
  schemaText += `## ${table}\n${cols.join('\n')}\n\n`;
}

return [{ json: { schemaText } }];
